"""DMD2 adversarial training over videoref streaming chains, scored on the fake score's window.

Chains, rollout, FAKE score training and DMD scoring follow
``MiniMaxH3VideoRefStreamingDMD``. The fake model additionally carries a
discriminator that classifies each window's target, the noisy video rows of
the window's unit and their noisy audio rows, in the window the fake score
reads: the teacher's window with ``meta_model.teacher_streaming``, otherwise
the student's. Sink, history, reference and picture rows are context of that
forward and are never scored. Every discriminator call packs the window
exactly as the fake score's full-condition forward does, with the same
fixed-window RoPE, reference rows, picture, Qwen context and kwargs, and
passes the target rows as explicit chunk ranges. The fake model must pool all
ranges of a sample into one chunk, as ``MiniMaxH3StreamingGANX0DiTSPV2`` does,
so every window sample yields exactly one logit.

Every window target is generated by the student, so every sample is scored.
Real samples are the clip's corpus latents of the window target inside the
corpus window: the same plans, reference rows and picture, with history read
from the chain head's corpus latents, which rollout write-back never touches.
The head's latents ride in every window's payload, so each rank of a UP group
builds them, and a resumed head brings them back. The corpus window's history
carries the same clean-condition perturbation with the same noise draws as
the fake score's window, so the two windows coincide while a chain still
reads corpus history, at its first window. A real target thus always
continues its own corpus history, although the fake target continues the
generator's history in every later window, and the discriminator cannot tell
real from fake by a seam between target and history. Fake samples in FAKE are
the final rollout x0 of the window target, placed in the fake score's window
exactly as FAKE places its training rows. GEN scores the generator's
graph-attached x0 of the drawn step, the same tensor its DMD loss scores.

Discriminator inputs follow causal DMD2. Each sample draws a paired timestep
from ``diffusion.gan_training_timesteps`` and its target is corrupted through
``fake_schedule``, or stays clean under that timestep label with
``gan_disc_clean_input``. ``gan_r1_lambda`` adds approximate R1 on the real
logits against targets perturbed by ``gan_r1_sigma`` noise. These draws stay
fresh under ``score_path: ode``, the only noise after its rollout, because a
corpus target lies on no rollout line and a fake target is corrupted as the
real one is.

The taps come from the fake model's full-condition forward, whatever
``cfg_fitting_guidance`` or ``fake_fitting_state`` make the fake score read,
and each discriminator call is its own forward that stops after the last tap.
The fake score's training forward cannot supply them: it reads FAKE's own
point and timesteps, not the final x0 at the discriminator's timesteps.
Per window this adds two discriminator forwards to FAKE, three with aR1, and
one to GEN, each with its backward.

FAKE returns the score loss, ``gan_lambda_disc`` times the fake-sample term
and the real term with its optional aR1 as three separate losses, so the
engine backpropagates each on its own graph. GEN adds ``gan_lambda_gen``
times the generator's non-saturating loss to the DMD loss.
``gen_model_context`` freezes the fake model and its discriminator while
input gradients reach the generator.

The discriminator lives in the fake model, so it checkpoints, resumes and
trains in the fake model's optimizer. A fake model loaded from a checkpoint
without it lists the discriminator in ``allow_missing``, and
``InitMiniMaxH3Discriminator`` initializes it fresh.

Expected configuration additions::

    meta_model:
      module: dev.yanzuolu.projects.minimax_h3_videoref.meta_models.minimax_h3_video_ref_streaming_dmd2
      class_name: MiniMaxH3VideoRefStreamingDMD2
      gan_lambda_disc: 1.0e-2
      gan_lambda_gen: 1.0
      gan_disc_clean_input: false
      gan_r1_lambda: 0.0
      gan_r1_sigma: 0.1

    diffusion:
      gan_training_timesteps:
        module: dev.yanzuolu.projects.minimax_h3.modeling.training_timesteps
        class_name: PairedUniformTrainingTimesteps
        args: {T: 1.0, shift: 6.0, audio_shift: 1.5}

    models:
      fake_model:
        module: dev.yanzuolu.projects.minimax_h3_videoref.modeling.build
        class_name: MiniMaxH3StreamingGANX0DiTSPV2
        args: {discriminator_tap_blocks: [1, 9, 17, 25], discriminator_num_queries: 2}
        adapter:
          target_modules: '^dit\\.(?:.*\\.)?(qkv_proj|out_proj|...)$'
          modules_to_save: [discriminator]
"""

from __future__ import annotations

from collections.abc import Iterator
from contextlib import contextmanager
from dataclasses import dataclass, fields, replace
from typing import Any

import torch
from torch.nn import functional as F

from dev.yanzuolu.common.diffusion import build_diffusion
from dev.yanzuolu.common.meter import get_running_average_meter
from dev.yanzuolu.common.phase import ExecutionPhase, execution_phase
from dev.yanzuolu.common.seed import RandomState, local_seed, yield_seed
from dev.yanzuolu.projects.minimax_h3.meta_models.minimax_h3_streaming_dmd import StreamingDMDInputs
from dev.yanzuolu.projects.minimax_h3.modeling.streaming import StreamingInputs
from dev.yanzuolu.projects.minimax_h3_videoref.meta_models.minimax_h3_video_ref_streaming_dmd import (
    MiniMaxH3VideoRefStreamingDMD,
    VideoRefStreamingDMDInputs,
)
from dev.yanzuolu.projects.minimax_h3_videoref.meta_models.minimax_h3_video_ref_streaming_pixel_dmd import (
    MiniMaxH3VideoRefStreamingPixelDMD,
)
from dev.yanzuolu.projects.minimax_h3_videoref.meta_models.minimax_h3_video_ref_streaming_rf import _ChainState

_Pair = tuple[list[torch.Tensor], list[torch.Tensor]]


@dataclass(frozen=True)
class VideoRefStreamingDMD2Inputs(VideoRefStreamingDMDInputs):
    """A chain window with the corpus window of its discriminator real samples.

    ``real_history`` holds the corpus window tensors in the layout of the fake
    score window's ``history`` and ``real_x0s`` the corpus latents of its
    noisy rows.
    """

    real_history: _Pair | None = None
    real_x0s: _Pair | None = None


class VideoRefStreamingDMD2Mixin:
    """See the module docstring for the scored rows, real and fake samples and losses."""

    def __init__(self, config: Any) -> None:
        super().__init__(config)
        options = config.meta_model
        self.gan_lambda_disc = float(options.get("gan_lambda_disc", 1.0e-2))
        self.gan_lambda_gen = float(options.get("gan_lambda_gen", 5.0e-3))
        self.gan_disc_clean_input = bool(options.get("gan_disc_clean_input", False))
        self.gan_r1_lambda = float(options.get("gan_r1_lambda", 0.0))
        self.gan_r1_sigma = float(options.get("gan_r1_sigma", 0.1))
        self.gan_training_timesteps = build_diffusion(
            {"gan_training_timesteps": config.diffusion.gan_training_timesteps}
        )["gan_training_timesteps"]
        if float(self.gan_training_timesteps.T) != float(self.fake_schedule.T):
            raise ValueError("gan_training_timesteps.T must match fake_schedule.T")

    @contextmanager
    def gen_model_context(self, models: dict[str, Any]) -> Iterator[None]:
        """Freeze the fake model and its discriminator while preserving input gradients."""
        fake = models["fake_model"]
        states = [parameter.requires_grad for parameter in fake.parameters()]
        fake.requires_grad_(False)
        try:
            with super().gen_model_context(models):
                yield
        finally:
            for parameter, state in zip(fake.parameters(), states, strict=True):
                parameter.requires_grad_(state)

    # ------------------------------------------------------------------
    # Real samples
    # ------------------------------------------------------------------

    def _start_chain(self, ctx: dict[str, Any]) -> _ChainState:
        """Also keep the head batch's corpus latents, which no write-back touches."""
        entry = super()._start_chain(ctx)
        entry.corpus = (list(ctx["batch"]["video_latents"]), list(ctx["batch"]["audio_latents"]))
        return entry

    def _chain_window_payload(self, entry: _ChainState, window: int) -> dict[str, Any]:
        """Every window carries the corpus, so every rank of a UP group builds the real samples."""
        return {**super()._chain_window_payload(entry, window),
                "corpus_video_latents": entry.corpus[0], "corpus_audio_latents": entry.corpus[1]}

    def _finish_dmd_window(
        self, inputs: VideoRefStreamingDMDInputs, *, view: dict[str, Any], plans: list[dict[str, Any]],
        rngs: list[RandomState], rng: RandomState,
    ) -> VideoRefStreamingDMD2Inputs:
        """Attach the corpus window history and noisy-row latents of the fake score's window.

        The history is built exactly as the fake score's window history, from
        the corpus instead of the working copies, with the same draws.
        """
        inputs = super()._finish_dmd_window(inputs, view=view, plans=plans, rngs=rngs, rng=rng)
        payload = view["encoded_batch"]
        corpus = tuple([value.float() for value in payload[f"corpus_{name}_latents"]] for name in ("video", "audio"))
        if self.teacher_streaming is None:
            history = self._window_history(corpus, plans, rng)
        else:
            _, history = self._teacher_window(dict(view, clean_latents=corpus), plans, rngs, None)
        targets = tuple([
            self._select(values[index], self._chunk_rows(plan, audio=bool(modality)), audio=bool(modality))
            for index, plan in enumerate(self._score_inputs(inputs).plans)
        ] for modality, values in enumerate(corpus))
        return VideoRefStreamingDMD2Inputs(
            **{field.name: getattr(inputs, field.name) for field in fields(inputs)},
            real_history=history, real_x0s=targets,
        )

    # ------------------------------------------------------------------
    # Discriminator
    # ------------------------------------------------------------------

    @staticmethod
    def _target_chunk_ranges(window: StreamingInputs, bounds: list[int]) -> tuple[torch.Tensor, torch.Tensor]:
        """Return each sample's noisy video and audio rows as ordered contiguous packed ranges."""
        device = window.token_tags.device
        ranges, samples = [], []
        for index, pack in enumerate(window.packs):
            audio = pack["audio_pos"].to(device).index_select(0, pack["audio_noisy_sel"].to(device))
            rows, _ = torch.cat((audio, pack["noisy_img_pos"].to(device))).sort()
            rows = rows + bounds[index]
            breaks = torch.nonzero(rows[1:] != rows[:-1] + 1).flatten() + 1
            starts = torch.cat((rows[:1], rows[breaks]))
            stops = torch.cat((rows[breaks - 1], rows[-1:])) + 1
            ranges.append(torch.stack((starts, stops), dim=1))
            samples.append(torch.full_like(starts, index))
        return torch.cat(ranges), torch.cat(samples)

    def _pred_gan_logits(
        self, fake_model: Any, inputs: StreamingDMDInputs, values: _Pair, timesteps: tuple[torch.Tensor, torch.Tensor],
    ) -> torch.Tensor:
        """Classify the window target through the fake model's full-condition window forward.

        ``values`` replace the noisy rows of ``inputs.history``. Returns one
        logit per sample shaped ``[B, 1]``.
        """
        window = inputs.window_inputs
        kwargs = self._streaming_kwargs(fake_model, window, **self._window_kwargs(inputs, values, timesteps))
        bounds = list(kwargs["packed_seq_params"]["cu_seqlens_q_host"])
        device = window.token_tags.device
        # Sequence-parallel alignment rows form a trailing document that is never live.
        lengths = torch.tensor([stop - start for start, stop in zip(bounds, bounds[1:])], dtype=torch.int32, device=device)
        ranges, samples = self._target_chunk_ranges(window, bounds)
        logits = fake_model(
            **kwargs, classify_mode=True,
            gan_video_timesteps=timesteps[0].to(device=device, dtype=torch.float32), gan_k_lens=lengths,
            gan_live_documents=torch.arange(lengths.numel(), device=device) < inputs.batch_size,
            gan_chunk_ranges=ranges, gan_chunk_sample_indices=samples,
        )
        if not isinstance(logits, torch.Tensor) or tuple(logits.shape) != (inputs.batch_size, 1):
            raise ValueError(
                "the fake model must pool each window target into one V2 chunk logit, e.g. "
                "dev.yanzuolu.projects.minimax_h3_videoref.modeling.build.MiniMaxH3StreamingGANX0DiTSPV2"
            )
        return logits

    def _prepare_gan_inputs(
        self, inputs: StreamingDMDInputs, latents: _Pair, rng: Any,
    ) -> tuple[_Pair, tuple[torch.Tensor, torch.Tensor]]:
        """Draw paired discriminator timesteps and corrupt ``latents`` unless inputs stay clean."""
        with local_seed(rng.seed % 2**31):
            drawn = self.gan_training_timesteps.sample_pair(
                (inputs.batch_size,), inputs.seqlens, inputs.seqlens.device,
            )
        rng.seed = yield_seed(rng.seed)
        timesteps = tuple(value.to(torch.float32) for value in drawn)
        if self.gan_disc_clean_input:
            return latents, timesteps
        noises = self._noise_rows(latents, rng)
        return tuple(
            self.fake_schedule.forward(values, noise, t) for values, noise, t in zip(latents, noises, timesteps, strict=True)
        ), timesteps

    @staticmethod
    @torch.no_grad()
    def _log_gan_logits(logits: torch.Tensor, prefix: str) -> None:
        get_running_average_meter().put_scalar(f"{prefix}/tap0", float(logits.float().mean()))

    # ------------------------------------------------------------------
    # Primitives
    # ------------------------------------------------------------------

    @execution_phase(ExecutionPhase.TRAIN_FORWARD)
    def prepare_fake(self, ctx: dict[str, Any]) -> dict[str, Any]:
        """Also writes the fake, real and optional aR1 discriminator inputs and timesteps."""
        ctx = super().prepare_fake(ctx)
        inputs, rng, rollout = ctx["fake_inputs"], ctx["rng"], ctx["rollout_x0s"]
        score = self._score_inputs(inputs)
        ctx["gan_fake_latents"], ctx["gan_fake_timesteps"] = self._prepare_gan_inputs(
            score, (rollout.video, rollout.audio), rng,
        )
        ctx["gan_real_latents"], ctx["gan_real_timesteps"] = self._prepare_gan_inputs(score, inputs.real_x0s, rng)
        if self.gan_r1_lambda > 0:
            noises = self._noise_rows(ctx["gan_real_latents"], rng)
            ctx["gan_real_perturbed_latents"] = tuple(
                [value + self.gan_r1_sigma * noise for value, noise in zip(values, modality, strict=True)]
                for values, modality in zip(ctx["gan_real_latents"], noises, strict=True)
            )
        return ctx

    @execution_phase(ExecutionPhase.TRAIN_FORWARD)
    def fake_loss(self, ctx: dict[str, Any]) -> dict[str, Any]:
        """Return the score loss, the fake-sample term and the real term with aR1 as separate losses."""
        ctx = super().fake_loss(ctx)
        fake_model, inputs = ctx["models"]["fake_model"], ctx["fake_inputs"]
        score = self._score_inputs(inputs)
        real = replace(score, history=inputs.real_history)
        fake_logits = self._pred_gan_logits(fake_model, score, ctx["gan_fake_latents"], ctx["gan_fake_timesteps"])
        real_logits = self._pred_gan_logits(fake_model, real, ctx["gan_real_latents"], ctx["gan_real_timesteps"])
        fake_term = F.softplus(fake_logits.float()).mean()
        real_term = F.softplus(-real_logits.float()).mean()
        real_graph_term = self.gan_lambda_disc * real_term
        meter = get_running_average_meter()
        if self.gan_r1_lambda > 0:
            perturbed_logits = self._pred_gan_logits(
                fake_model, real, ctx["gan_real_perturbed_latents"], ctx["gan_real_timesteps"],
            )
            ar1_term = (real_logits.float() - perturbed_logits.float()).pow(2).mean()
            real_graph_term = real_graph_term + self.gan_r1_lambda * ar1_term
            meter.put_scalar("fake_losses/gan_ar1", float(ar1_term.detach()))
        self._log_gan_logits(fake_logits, "fake_losses/gan_logits_fake_mean")
        self._log_gan_logits(real_logits, "fake_losses/gan_logits_real_mean")
        meter.put_scalar("fake_losses/gan_loss", float((fake_term + real_term).detach()))
        # Separate terms give each discriminator forward its own backward graph,
        # see engines/dmd.py::_fake_backward. aR1 shares real_logits with the
        # real term, so the two stay one term.
        ctx["fake_loss"] = (ctx["fake_loss"], self.gan_lambda_disc * fake_term, real_graph_term)
        return ctx

    @execution_phase(ExecutionPhase.TRAIN_FORWARD)
    def gen_loss(self, ctx: dict[str, Any]) -> dict[str, Any]:
        """Add the generator's non-saturating GAN loss on the scored x0 to the DMD loss."""
        ctx = super().gen_loss(ctx)
        inputs = self._score_inputs(ctx["gen_inputs"])
        latents, timesteps = self._prepare_gan_inputs(inputs, ctx["gen_x0s"], ctx["rng"])
        logits = self._pred_gan_logits(ctx["models"]["fake_model"], inputs, latents, timesteps)
        gan_loss = F.softplus(-logits.float()).mean()
        self._log_gan_logits(logits, "dmd_losses/gan_logits_mean")
        get_running_average_meter().put_scalar("dmd_losses/gan_loss", float(gan_loss.detach()))
        ctx["gen_loss"] = ctx["gen_loss"] + self.gan_lambda_gen * gan_loss
        return ctx


class MiniMaxH3VideoRefStreamingDMD2(VideoRefStreamingDMD2Mixin, MiniMaxH3VideoRefStreamingDMD):
    """Streaming DMD2 over videoref chains whose fake score and discriminator read the teacher's window."""


class MiniMaxH3VideoRefStreamingPixelDMD2(VideoRefStreamingDMD2Mixin, MiniMaxH3VideoRefStreamingPixelDMD):
    """Streaming DMD2 of the pixel-conditioned generator against Ref2VA scores and discriminator."""


EntryClass = MiniMaxH3VideoRefStreamingDMD2

__all__ = [
    "MiniMaxH3VideoRefStreamingDMD2",
    "MiniMaxH3VideoRefStreamingPixelDMD2",
    "VideoRefStreamingDMD2Inputs",
    "VideoRefStreamingDMD2Mixin",
    "EntryClass",
]
